#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int marks;
};

void bonusByValue(Student s) {
    s.marks += 5;
}

void bonusByRef(Student &s) {
    s.marks += 5;
}

void show(const Student &s) {
    cout << s.name << ": " << s.marks << endl;
}

int main() {
    Student a = {"Ali", 60};
    bonusByValue(a);
    show(a);
    bonusByRef(a);
    show(a);
    return 0;
}

#include <iostream>
using namespace std;

struct Point {
    int x, y;
};

void show(Point p) {
    cout << "(" << p.x << ", " << p.y << ")" << endl;
}

void moveRight(Point &p, int d) {
    p.x += d;
}

double distanceFromOrigin(const Point &p) {
    return p.x * p.x + p.y * p.y;
}

int main() {
    Point a = {2, 3};
    show(a);
    moveRight(a, 5);
    show(a);
    cout << "Squared distance: " << distanceFromOrigin(a) << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int marks;
};

void bonus(Student *p) {
    p->marks += 5;
}

int main() {
    Student s = {"Sara", 70};
    Student *ptr = &s;
    bonus(&s);
    cout << s.name << " " << s.marks << endl;
    bonus(ptr);
    cout << ptr->name << " " << ptr->marks << endl;
    cout << (*ptr).marks << endl;
    return 0;
}

